-- MySQL 8.0。会议预算收费标准库扩列 + 灌入公司报价单/成本单模板全部费用项（2026-11-20）。
-- 可重跑（列存在性守卫 + INSERT IGNORE by fee_key 唯一键）。
START TRANSACTION;

SET @col_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='project_budget_fee_standard' AND COLUMN_NAME='catalog');
SET @ddl := IF(@col_exists = 0,
  'ALTER TABLE `project_budget_fee_standard` ADD COLUMN `catalog` VARCHAR(20) NULL COMMENT ''类目：ELEC电子物料/PRINT小型制作/ONLINE线上直播/BUILD大型搭建/STAFF人员服务/SPECIAL非常规'' AFTER `scene`, ADD COLUMN `category` VARCHAR(20) NULL COMMENT ''小类（模板A列，如设计类）'' AFTER `catalog`, ADD COLUMN `detail` VARCHAR(500) NULL COMMENT ''详细内容/规格说明'' AFTER `name`, ADD COLUMN `spec` VARCHAR(100) NULL COMMENT ''规格/时效'' AFTER `detail`, ADD COLUMN `cost_price` DECIMAL(14,2) NULL COMMENT ''成本价（成本单/供应商价）'' AFTER `default_value`, ADD COLUMN `min_profit` DECIMAL(14,2) NULL COMMENT ''最低利润要求（报价-成本下限）'' AFTER `cost_price`',
  'SELECT ''fee_standard columns already exist'' AS info');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @col_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='project_budget_item' AND COLUMN_NAME='cost_price');
SET @ddl := IF(@col_exists = 0,
  'ALTER TABLE `project_budget_item` ADD COLUMN `cost_price` DECIMAL(14,2) NULL COMMENT ''成本单价'' AFTER `unit_price`, ADD COLUMN `cost_amount` DECIMAL(14,2) NULL COMMENT ''成本金额=quantity*cost_price（服务端计算）'' AFTER `amount`',
  'SELECT ''item columns already exist'' AS info');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @col_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS
  WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='project_budget' AND COLUMN_NAME='cost_total');
SET @ddl := IF(@col_exists = 0,
  'ALTER TABLE `project_budget` ADD COLUMN `cost_total` DECIMAL(14,2) NOT NULL DEFAULT 0 COMMENT ''成本合计'' AFTER `total_amount`, ADD COLUMN `service_rate` DECIMAL(5,4) NOT NULL DEFAULT 0.0600 COMMENT ''服务费率（历史结算单口径 6%）'' AFTER `cost_total`, ADD COLUMN `tax_rate` DECIMAL(5,4) NOT NULL DEFAULT 0.0600 COMMENT ''增值税率（历史结算单口径 6%）'' AFTER `service_rate`',
  'SELECT ''budget columns already exist'' AS info');
PREPARE stmt FROM @ddl; EXECUTE stmt; DEALLOCATE PREPARE stmt;


COMMIT;
